// org.site.list — generated by `pnpm gen:query org site-list`. Read through ../repository.ts; RLS limits the
// rows to what the actor may see. Queries run read-only (02-architecture §3).
import { z } from 'zod';
import { defineQuery } from '../../kernel/index.ts';
import { orgPermissions } from '../permissions.ts';

export const siteList = defineQuery({
  name: 'org.site.list',
  permission: orgPermissions.siteList,
  input: z.object({}),
  handle: () => Promise.resolve<{ id: string }[]>([]),
});
